using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ClarityWhirlwindAction", menuName = "Data/Battle/Battle Actions/Austra/ClarityWhirlwind Action")]
public class ClarityWhirlwindAction : PurifyCounterBasedAction
{
	[Header("Clarity Whirlwind Specifics")]
	[SerializeField]
	protected OmenLogic targetToPurifyLogic;

	[SerializeField]
	protected PurifyAction secondPurifyAction;

	[SerializeField]
	private PurifyAction purifyActionToChange;

	public PurifyAction SecondPurifyAction => secondPurifyAction;

	protected List<DiceInstance> playerDiceHand => ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		for (int i = 0; i < playerDiceHand.Count; i++)
		{
			bool flag = false;
			bool flag2 = false;
			bool flag3 = false;
			DiceInstance diceInstance2 = playerDiceHand[i];
			if (diceInstance2.ActionFace.BattleAction is PurifyAction)
			{
				flag2 = true;
				flag = true;
			}
			if (diceInstance2.ActionFace.EnableSecondAction && diceInstance2.ActionFace.SecondBattleAction is PurifyAction)
			{
				flag = true;
				flag3 = true;
			}
			if (flag2 && flag3)
			{
				ChangeBothActions(diceInstance2);
			}
			else if (flag2)
			{
				ChangeFirstAction(diceInstance2);
			}
			else if (flag3)
			{
				ChangeSecondAction(diceInstance2);
			}
			if (flag)
			{
				if (IsThirdVFXEnabled())
				{
					GetThirdVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance2);
				}
				diceInstance2.UpdateDiceFace();
			}
		}
		if (IsVFXEnabled())
		{
			if (enableVFXDelay)
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXAnimation(target, amount, source));
				ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			}
			else
			{
				PlaySFX();
				SpawnVFX(4f);
				DealPurify(target, amount, source);
			}
		}
		else
		{
			DealPurify(target, amount, source);
		}
		void ChangeBothActions(DiceInstance diceInstance)
		{
			diceInstance.ActionFace.BattleAction = purifyActionToChange;
			diceInstance.ActionFace.SetActionModifierLock(isLocked: false);
			diceInstance.ActionFace.SecondBattleAction = purifyActionToChange;
			diceInstance.ActionFace.SetSecondActionModifierLock(isLocked: false);
			diceInstance.UpdateActionValueModifier();
		}
		void ChangeFirstAction(DiceInstance diceInstance)
		{
			diceInstance.ActionFace.BattleAction = purifyActionToChange;
			diceInstance.ActionFace.SetActionModifierLock(isLocked: false);
			diceInstance.UpdateActionValueModifier();
		}
		void ChangeSecondAction(DiceInstance diceInstance)
		{
			diceInstance.ActionFace.SecondBattleAction = purifyActionToChange;
			diceInstance.ActionFace.SetSecondActionModifierLock(isLocked: false);
			diceInstance.UpdateActionValueModifier();
		}
	}

	public override int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		return base.playerRunData.RandomPurifyAmount;
	}

	private void DealPurify(GameObject target, int purifyAmountMultiplier, GameObject source)
	{
		List<GameObject> targets = targetToPurifyLogic.GetTargets();
		for (int i = 0; i < targets.Count; i++)
		{
			SpawnSecondVFX(GetVFXOwnerPosition(targets[i]), 3f);
		}
		secondPurifyAction.CastTargetAmount(target, purifyAmountMultiplier, source);
		if (PurifyCounter(checkConditionToBeCastedOrPreview: false) > 0)
		{
			targetToPurifyLogic.ActivateOmen(purifyCorruptAction, PurifyAmount(purifyAmountMultiplier), null, null);
		}
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	private IEnumerator VFXAnimation(GameObject target, int normalPurifyAmount, GameObject source)
	{
		SpawnVFX(4f);
		PlaySFX();
		yield return new WaitForSeconds(vfxDelay);
		DealPurify(target, normalPurifyAmount, source);
	}
}
